t.'/app/services/TelefoniaVentasLlamadasService.php';\n    $calls=new TelefoniaVentasLlamadasService();\n    try {$call=$calls->obtener($usuarioId,$pbxCallId,(string)($_GET['extension']??''));}\n    catch(DomainException $e){http_response_code(404);exit('No hay un tramo autorizado para esta llamada.');}\n    if(!$call['finalizada']||!$call['conectada']||!TelefoniaResultadoVentasService::esConversacion($call['registro']['resultado']??'')){\n        http_response_code(404);exit('Este intento no tiene reproducción de audio habilitada.');\n    }\n    $ids=$call['segmentos'];\n    if(isset($_GET['verificar'])){\n        $service=new ZadarmaRecordingService(false);$info=[];$temporary=false;\n        foreach($ids as $i=>$id){try{$r=$service->obtenerGrabacionPorCallId($id);if(!empty($r['link']))$info[]=($call['segmentos_info'][$i]??[])+['indice'=>$i];}catch(Throwable $e){$temporary=true;error_log('[ventas_audio] RECORD_TEMPORARY ref='.substr(hash('sha256',$pbxCallId),0,12));}}","    require_once $root.'/app/services/TelefoniaVentasLlamadasService.php';\n    $calls=new TelefoniaVentasLlamadasService();\n    try {$call=$calls->obtener($usuarioId,$pbxCallId,(string)($_GET['extension']??''));}\n    catch(DomainException $e){http_response_code(404);exit('No hay un tramo autorizado para esta llamada.');}\n    $transferida=($call['direccion']??'')==='Entrante' &&\n        (string)($call['origen_extension']??'')!=='' && !empty($call['solicitud_id']);\n    if((!$transferida&&!$call['finalizada'])||!$call['conectada']||\n        !TelefoniaResultadoVentasService::esConversacion($call['registro']['resultado']??'')){\n        http_response_code(404);exit('Este intento no tiene reproducción de audio habilitada.');\n    }\n    if($transferida){\n        // El resultado humano puede guardarse sin END de Zadarma. Verificar\n        // identidad y ruta comercial en la operación PBX exacta; devolver\n        // tantos segmentos NOTIFY_RECORD como hayan sido corroborados.\n        require_once $root.'/app/services/TelefoniaGrabacionesTransferenciaVentasService.php';\n        $db=(new Database())->connect(false);\n        $svc=new TelefoniaGrabacionesTransferenciaVentasService($db);\n        $provider=new ZadarmaRecordingService(false);\n        $service=$provider; // La descarga Range final reutiliza el mismo proveedor.\n        try{\n            $response=$svc->resolver($pbxCallId,$usuarioId,'destino',(string)$call['extension'],\n                [$provider,'obtenerGrabacionPorCallId'],\n                isset($_GET['verificar'])?[$provider,'estadisticasPbx']:null);\n        }catch(DomainException $e){\n            http_response_code(404);exit('No hay tramos transferidos autorizados.');\n        }\n        if(isset($_GET['verificar'])){\n            unset($response['records']);\n            header('Content-Type: application/json; charset=utf-8');\n            header('Cache-Control: private, no-store');\n            echo json_encode($response,JSON_UNESCAPED_UNICODE);exit;\n        }\n        $index=filter_var($_GET['segmento']??null,FILTER_VALIDATE_INT,\n            ['options'=>['min_range'=>0,'max_range'=>7]]);\n        if($index===false||$index===null||!isset($response['records'][$index])){\n            http_response_code(404);exit('El tramo solicitado no está disponible.');\n        }\n        $recording=$response['records'][$index];\n    }else{\n    $ids=$call['segmentos'];\n    if(isset($_GET['verificar'])){\n        $service=new ZadarmaRecordingService(false);$info=[];$temporary=false;\n        foreach($ids as $i=>$id){try{$r=$service->obtenerGrabacionPorCallId($id);if(!empty($r['link']))$info[]=($call['segmentos_info'][$i]??[])+['indice'=>$i];}catch(Throwable $e){$temporary=true;error_log('[ventas_audio] RECORD_TEMPORARY ref='.substr(hash('sha256',$pbxCallId),0,12));}}"],["    if($segment===false||$segment<0||!isset($ids[$segment])){http_response_code(404);exit('No hay audio confirmado para tu extensión.');}\n    // Resolver cada ID autorizado; nunca pedir audio global del PBX.\n    $service=new ZadarmaRecordingService();$recording=$service->obtenerGrabacionPorCallId($ids[$segment]);\n    if(!$recording||empty($recording['link'])){http_response_code(404);exit('La grabación aún no está disponible en Zadarma.');}\n\n    $audio = $service->descargarGrabacion((string)$recording['link'], $rangeHeader);\n    $body = (string)($audio['body'] ?? '');\n    if ($body === '') {","    if($segment===false||$segment<0||!isset($ids[$segment])){http_response_code(404);exit('No hay audio confirmado para tu extensión.');}\n    // Resolver cada ID autorizado; nunca pedir audio global del PBX.\n    $service=new ZadarmaRecordingService();$recording=$service->obtenerGrabacionPorCallId($ids[$segment]);\n    if(!$recording||empty($recording['link'])){http_response_code(404);exit('La grabación aún no está disponible en Zadarma.');}\n    } // Fin del reproductor original de llamada individual.\n\n    $audio = $service->descargarGrabacion((string)$recording['link'], $rangeHeader);\n    $body = (string)($audio['body'] ?? '');\n    if ($body === '') {"]]},{"path":"prueba_telefonia/api/grabacion_transferida_pbx.php","pairs":[["require_once $root . '/app/services/TelefoniaRecepcionMarketingService.php';\nrequire_once $root . '/app/services/ZadarmaRecordingService.php';\nrequire_once $root . '/app/helpers/ZadarmaPbxIdentifierHelper.php';\nrequire_once $root . '/app/services/TelefoniaAudioTransferidoService.php';\nheader('Cache-Control: private, no-store');\nheader('X-Content-Type-Options: nosniff');\nif (($_SERVER['REQUEST_METHOD'] ?? '') !== 'GET') { http_response_code(405); exit; }\n$userId = (int)($_SESSION['usuario_id'] ?? 0);","require_once $root . '/app/services/TelefoniaRecepcionMarketingService.php';\nrequire_once $root . '/app/services/ZadarmaRecordingService.php';\nrequire_once $root . '/app/helpers/ZadarmaPbxIdentifierHelper.php';\nrequire_once $root . '/app/services/TelefoniaAudioTransferidoService.php';\nrequire_once $root . '/app/services/TelefoniaGrabacionesTransferenciaVentasService.php';\nheader('Cache-Control: private, no-store');\nheader('X-Content-Type-Options: nosniff');\nif (($_SERVER['REQUEST_METHOD'] ?? '') !== 'GET') { http_response_code(405); exit; }\n$userId = (int)($_SESSION['usuario_id'] ?? 0);"],["        foreach ((new TelefoniaRecepcionMarketingService())->resumen($userId)['llamadas'] as $call) {\n            if ($call['pbx_call_id']===$pbx && $call['estado']==='Transferida' && !empty($call['finalizada']) && empty($call['excluir_grabacion'])) {$allowed=true;break;}\n        }\n        if (!$allowed) throw new DomainException('ACCESO_NO_AUTORIZADO');\n        // El receptor de la transferencia se toma del historial privado.\n        $receiver=(string)($call['destino_transferencia']??'');\n        $q=$db->prepare('SELECT * FROM telefonia_zadarma_eventos WHERE pbx_call_id=? ORDER BY id');\n        $q->bind_param('s',$pbx);$q->execute();$events=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();\n        $parts=TelefoniaPbxSegmentosService::deEventos($events,$ext,[$receiver]);\n        $records=[];$info=[];\n        foreach($parts['segmentos'] as $i=>$id){$r=$service->obtenerGrabacionPorCallId($id);if(!empty($r['link'])){$records[$i]=$r;$info[]=($parts['segmentos_info'][$i]??[])+['indice'=>$i];}}\n        $result=['ok'=>true,'estado'=>$records?'DISPONIBLE':'GRABACION_EN_PREPARACION','disponible'=>(bool)$records,'segmentos'=>count($records),'segmentos_info'=>$info];\n    } else {\n        $cacheKey=$ext.'|'.$pbx;$cache=$_SESSION['impe_audio_transferido'][$cacheKey]??[];\n        $cached=time()-(int)($cache['at']??0)<3600?($cache['rows']??[]):[];\n        $stats=isset($_GET['verificar'])&&(!$cached||time()-(int)$cache['at']>=60)?[$service,'estadisticasPbx']:null;","        foreach ((new TelefoniaRecepcionMarketingService())->resumen($userId)['llamadas'] as $call) {\n            if ($call['pbx_call_id']===$pbx && $call['estado']==='Transferida' && !empty($call['finalizada']) && empty($call['excluir_grabacion'])) {$allowed=true;break;}\n        }\n        if (!$allowed) throw new DomainException('ACCESO_NO_AUTORIZADO');\n        $comercial=new TelefoniaGrabacionesTransferenciaVentasService($db);\n        if($comercial->operacionComercial($pbx,$userId,'origen')){\n            // Recepción también consulta ambos tramos de sus transferencias\n            // a Ventas. Nada se infiere por teléfono, fecha o fila saliente.\n            $result=$comercial->resolver($pbx,$userId,'origen',$ext,\n                [$service,'obtenerGrabacionPorCallId'],\n                isset($_GET['verificar'])?[$service,'estadisticasPbx']:null);\n            $records=$result['records'];\n        }else{\n            // Conservar íntegra la política anterior para transferencias al\n            // Analista y demás destinos no comerciales.\n            $receiver=(string)($call['destino_transferencia']??'');\n            $q=$db->prepare('SELECT * FROM telefonia_zadarma_eventos WHERE pbx_call_id=? ORDER BY id');\n            $q->bind_param('s',$pbx);$q->execute();$events=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();\n            $parts=TelefoniaPbxSegmentosService::deEventos($events,$ext,[$receiver]);\n            $records=[];$info=[];\n            foreach($parts['segmentos'] as $i=>$id){$r=$service->obtenerGrabacionPorCallId($id);if(!empty($r['link'])){$records[$i]=$r;$info[]=($parts['segmentos_info'][$i]??[])+['indice'=>$i];}}\n            $result=['ok'=>true,'estado'=>$records?'DISPONIBLE':'GRABACION_EN_PREPARACION','disponible'=>(bool)$records,'segmentos'=>count($records),'segmentos_info'=>$info];\n        }\n    } else {\n        $cacheKey=$ext.'|'.$pbx;$cache=$_SESSION['impe_audio_transferido'][$cacheKey]??[];\n        $cached=time()-(int)($cache['at']??0)<3600?($cache['rows']??[]):[];\n        $stats=isset($_GET['verificar'])&&(!$cached||time()-(int)$cache['at']>=60)?[$service,'estadisticasPbx']:null;"]]}],"newService":{"path":"app/services/TelefoniaGrabacionesTransferenciaVentasService.php","content":"<?php\ndeclare(strict_types=1);\nrequire_once __DIR__.'/../helpers/ZadarmaPbxIdentifierHelper.php';\n\n/**\n * Una llamada transferida es un grupo PBX con varias grabaciones.\n * Los NOTIFY_RECORD firmados aportan identificadores, NO identifican la\n * extension responsable. Nunca se atribuyen audios por numero/fecha.\n */\nfinal class TelefoniaGrabacionesTransferenciaVentasService\n{\n    public function __construct(private mysqli $db) {}\n\n    /** Prueba pura de propiedad del grupo: eventos PBX firmados y respuesta 150.\n     * No se usa teléfono, fecha ni una referencia de audio enviada por frontend. */\n    public static function referenciasVerificadas(array $events,string $source,string $dest): array\n    {\n        if($source===$dest||!preg_match('/^[0-9]{3,6}$/D',$source)||\n            !preg_match('/^[0-9]{3,6}$/D',$dest))\n            throw new DomainException('ACCESO_NO_AUTORIZADO');\n        $sourceStarted=false;$destAnswered=false;$otherParticipant=false;$refs=[];\n        foreach($events as $event){\n            $kind=(string)($event['evento']??'');\n            $internal=trim((string)($event['internal']??''));\n            if(in_array($kind,['NOTIFY_INTERNAL','NOTIFY_ANSWER','NOTIFY_OUT_START','NOTIFY_END','NOTIFY_OUT_END'],true) &&\n                preg_match('/^[0-9]{3,6}$/D',$internal) && $internal!==$source && $internal!==$dest)\n                $otherParticipant=true;\n            if($kind==='NOTIFY_OUT_START'&&$internal===$source)$sourceStarted=true;\n            if($sourceStarted&&$kind==='NOTIFY_ANSWER'&&$internal===$dest)$destAnswered=true;\n            if($kind!=='NOTIFY_RECORD')continue;\n            $id=trim((string)($event['call_id_with_rec']??''));\n            if(!ZadarmaPbxIdentifierHelper::callIdValido($id))continue;\n            if(!isset($refs[$id]))$refs[$id]=['id'=>$id,'inicio'=>'','segundos'=>null,\n                'extension'=>'','etiqueta'=>'Tramo PBX · participante por verificar'];\n        }\n        if(!$sourceStarted||!$destAnswered||$otherParticipant)\n            throw new DomainException('ACCESO_NO_AUTORIZADO');\n        if(count($refs)>8)throw new DomainException('TRAMO_PENDIENTE_VINCULACION');\n        return $refs;\n    }\n\n    /** También permite conservar el servicio histórico del Analista. */\n    public function operacionComercial(string $pbx,int $user,string $rol): bool\n    {\n        $prop=$rol==='origen'?'o.origen_usuario':'o.destino_usuario';\n        $stmt=$this->db->prepare(\"SELECT o.id,d.ruta_json FROM telefonia_transferencia_operaciones o\n            INNER JOIN telefonia_disponibilidad d\n              ON d.referencia=BINARY o.referencia\n             AND d.origen_usuario=o.origen_usuario AND d.destino_usuario=o.destino_usuario\n             AND d.origen_extension=BINARY o.origen_extension\n             AND d.destino_extension=BINARY o.destino_extension\n            WHERE o.referencia=BINARY ? AND $prop=? AND o.estado='ENTREGADA'\n              AND d.estado IN ('ENVIANDO','ENVIADA','TRANSFERIDA','SIN_CONFIRMAR','SIN_RESPUESTA')\n            LIMIT 2\");\n        $stmt->bind_param('si',$pbx,$user);$stmt->execute();\n        $rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();\n        if(count($rows)!==1)return false;\n        $route=json_decode((string)$rows[0]['ruta_json'],true)?:[];\n        return ($route['tipo']??'')==='PROSPECTO';\n    }\n\n    /**\n     * @return array{ok:bool,estado:string,disponible:bool,segmentos:int,segmentos_info:array,records:array}\n     * No almacenar enlaces del proveedor; se vuelven a resolver por peticion.\n     */\n    public function resolver(string $pbx,int $user,string $rol,string $ext,\n                             callable $record,?callable $stats=null): array\n    {\n        if(!preg_match('/^[A-Za-z0-9_-]{6,100}$/D',$pbx)||\n            !preg_match('/^[0-9]{3,6}$/D',$ext)||!in_array($rol,['origen','destino'],true))\n            throw new DomainException('ACCESO_NO_AUTORIZADO');\n        $owner=$rol==='origen'?'o.origen_usuario':'o.destino_usuario';\n        $ownExtension=$rol==='origen'?'o.origen_extension':'o.destino_extension';\n        $sql=\"SELECT o.*,d.ruta_json FROM telefonia_transferencia_operaciones o\n            INNER JOIN telefonia_disponibilidad d\n              ON d.referencia=BINARY o.referencia AND d.origen_usuario=o.origen_usuario\n             AND d.destino_usuario=o.destino_usuario\n             AND d.origen_extension=BINARY o.origen_extension\n             AND d.destino_extension=BINARY o.destino_extension\n            WHERE o.referencia=BINARY ? AND $owner=? AND $ownExtension=BINARY ?\n              AND o.estado='ENTREGADA'\n              AND d.estado IN ('ENVIANDO','ENVIADA','TRANSFERIDA','SIN_CONFIRMAR','SIN_RESPUESTA')\n            LIMIT 2\";\n        $s=$this->db->prepare($sql);$s->bind_param('sis',$pbx,$user,$ext);\n        $s->execute();$ops=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();\n        if(count($ops)!==1)throw new DomainException('ACCESO_NO_AUTORIZADO');\n        $op=$ops[0];$route=json_decode((string)$op['ruta_json'],true)?:[];\n        if(($route['tipo']??'')!=='PROSPECTO' ||\n            (int)($route['responsable_id']??0)!==(int)$op['destino_usuario'] ||\n            (string)($route['extension']??'')!==(string)$op['destino_extension'] ||\n            (string)($route['referencia_llamada']??'')!==$pbx)\n            throw new DomainException('ACCESO_NO_AUTORIZADO');\n        $q=$this->db->prepare('SELECT id,evento,internal,call_id_with_rec,received_at,payload_json\n            FROM telefonia_zadarma_eventos WHERE pbx_call_id=BINARY ? ORDER BY id');\n        $q->bind_param('s',$pbx);$q->execute();\n        $events=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();\n        $source=(string)$op['origen_extension'];$dest=(string)$op['destino_extension'];\n        $refs=self::referenciasVerificadas($events,$source,$dest);\n        // Estadísticas oficiales: corroboran metadatos para un call_id ya\n        // verificado, sin incorporar por proximidad otros audios ni alterar el\n        // índice de reproducción estable durante el GET posterior.\n        if($stats&&$refs){\n            try{\n                $date=new DateTimeImmutable((string)$events[0]['received_at'],new DateTimeZone('America/Mexico_City'));\n                $rows=$stats($date->modify('-1 day')->format('Y-m-d H:i:s'),\n                             $date->modify('+1 day')->format('Y-m-d H:i:s'));\n                if(count($rows)<1000){\n                    $seen=[];\n                    foreach($rows as $entry){\n                        if(!is_array($entry)||!hash_equals($pbx,(string)($entry['pbx_call_id']??'')))continue;\n                        $id=ZadarmaPbxIdentifierHelper::callIdDeFila($entry);\n                        if(!isset($refs[$id]))continue;\n                        $sip=(string)($entry['sip']??'');\n                        if(isset($seen[$id])){$refs[$id]['etiqueta']='Tramo PBX · identidad por verificar';continue;}\n                        $seen[$id]=true;\n                        $refs[$id]['inicio']=(string)($entry['callstart']??'');\n                        $seconds=filter_var($entry['seconds']??null,FILTER_VALIDATE_INT,\n                            ['options'=>['min_range'=>0,'max_range'=>86400]]);\n                        if($seconds!==false)$refs[$id]['segundos']=$seconds;\n                        if($sip===$source||$sip===$dest){\n                            $refs[$id]['extension']=$sip;\n                            $refs[$id]['etiqueta']=$sip===$source?\n                                'Recepción · Ext. '.$source:'Asesor · Ext. '.$dest;\n                        }\n                    }\n                }\n            }catch(Throwable $e){\n                error_log('[ventas_tramos] Estadistica temporal '.substr(hash('sha256',$pbx),0,12));\n            }\n        }\n        $result=['ok'=>true,'estado'=>'GRABACION_EN_PREPARACION','disponible'=>false,\n            'segmentos'=>0,'segmentos_info'=>[],'records'=>[]];\n        $available=0;$missing=0;\n        foreach(array_values($refs) as $i=>$part){\n            try{\n                $audio=$record($part['id']);\n                $link=(string)($audio['link']??'');\n                if(!$link||!filter_var($link,FILTER_VALIDATE_URL)||\n                    !str_starts_with(strtolower($link),'https://')){$missing++;continue;}\n                $result['records'][$i]=$audio;\n                $result['segmentos_info'][]=['indice'=>$i,'tramo'=>$i+1,\n                    'etiqueta'=>$part['etiqueta'],'extension'=>$part['extension'],\n                    'segundos'=>$part['segundos']];\n                $available++;\n            }catch(Throwable $e){$missing++;}\n        }\n        $result['segmentos']=$available;$result['disponible']=$available>0;\n        $result['estado']=$available?($missing?'DISPONIBLE_PARCIAL':'DISPONIBLE'):\n            ($refs?'GRABACION_EN_PREPARACION':'SIN_GRABACION_REPORTADA');\n        return $result;\n    }\n}\n"}}''')
def die(msg):
    sys.stderr.write('CONFLICTO: '+msg+'\n');sys.exit(2)
if len(sys.argv)<2 or sys.argv[1] not in ('--check','--apply','--restore'):
    sys.stderr.write('Uso: IMPE_CRM_PUBLIC=/ruta/public_html bash script --check|--apply|--restore [respaldo]\n');sys.exit(1)
mode=sys.argv[1]
root_arg=os.environ.get('IMPE_CRM_PUBLIC','')
if not root_arg:die('Falta IMPE_CRM_PUBLIC.')
root=Path(root_arg).resolve()
if not (root/'index.php').is_file():die('Raiz del CRM no reconocida.')
backup_root=Path(os.environ.get('IMPE_CRM_BACKUPS',str(Path.home()/'impe-ventas-resultados-backups'))).resolve()
if backup_root==root or backup_root in root.parents or root in backup_root.parents:
    die('El respaldo debe estar fuera de public_html.')
def checksum(data):return hashlib.sha256(data).hexdigest()
def get(name,required=True):
    p=root/name
    if p.is_symlink() or root not in p.resolve().parents:
        die('Ruta no permitida: '+name)
    if required and not p.is_file():die('Archivo ausente: '+name)
    if not required and p.exists() and not p.is_file():die('Ruta no es archivo: '+name)
    return p
def replace(p,data,permissions):
    fd,tmp=tempfile.mkstemp(prefix='.impe-tramos-',dir=str(p.parent))
    try:
        os.fchmod(fd,permissions)
        with os.fdopen(fd,'wb') as out:
            out.write(data);out.flush();os.fsync(out.fileno())
        os.replace(tmp,str(p))
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
def syntax(path,data):
    ext='.php' if path.endswith('.php') else '.js'
    program='php' if ext=='.php' else 'node'
    if not shutil.which(program):
        if ext=='.php':die('No hay intérprete PHP para comprobación.')
        print('AVISO: Node.js no disponible en Hostinger; JS verificado por CI.')
        return
    fd,name=tempfile.mkstemp(suffix=ext)
    try:
        with os.fdopen(fd,'wb') as out:out.write(data)
        c=subprocess.run([program,'-l' if ext=='.php' else '--check',name],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        if c.returncode:die('Error de sintaxis: '+path+' '+(c.stdout+c.stderr).decode('utf8','replace')[-400:])
    finally:
        if os.path.exists(name):os.unlink(name)
allfiles=[x['path'] for x in SPECS['mods']]+[SPECS['newService']['path']]
if len(allfiles)!=6 or len(set(allfiles))!=6:die('Manifiesto de archivos alterado.')
if mode=='--restore':
    if len(sys.argv)!=3:die('Indica respaldo generado por este publicador.')
    backup=Path(sys.argv[2]).resolve()
    if backup_root not in backup.parents or backup.is_symlink():die('Respaldo no autorizado.')
    manifest=backup/'manifest.json'
    if not manifest.is_file():die('Falta el manifiesto.')
    records=json.loads(manifest.read_text(encoding='utf8'))
    if set(x['path'] for x in records)!=set(allfiles):die('Respaldo de otra entrega.')
    plan=[]
    for x in records:
        p=get(x['path'],not x['created'])
        current=p.read_bytes() if p.exists() else None
        if x['created']:
            if current is not None and checksum(current)!=x['new_sha']:die('Servicio nuevo modificado externamente.')
            plan.append((p,None,x['permissions'],current is not None))
        else:
            original=(backup/x['backup']).read_bytes()
            if checksum(original)!=x['old_sha']:die('Respaldo alterado: '+x['path'])
            if current is None or checksum(current) not in (x['old_sha'],x['new_sha']):die('Archivo editado tras la publicacion: '+x['path'])
            plan.append((p,original,x['permissions'],checksum(current)==x['new_sha']))
    for p,old,permissions,needed in plan:
        if not needed:continue
        if old is None:p.unlink()
        else:replace(p,old,permissions)
    print('OK: restauracion validada. Base de datos, grabaciones y Analista intactos.')
    sys.exit(0)
if len(sys.argv)!=2:die('Argumentos adicionales no previstos.')
plan=[]
for row in SPECS['mods']:
    p=get(row['path']);original=p.read_bytes()
    try:content=original.decode('utf8')
    except UnicodeDecodeError:die('Archivo no UTF8: '+row['path'])
    if b'\r\n' in original and original.count(b'\r\n')!=original.count(b'\n'):
        die('Saltos de línea mixtos: '+row['path'])
    crlf=b'\r\n' in original
    source=content.replace('\r\n','\n');new=source;oldhits=0;newhits=0
    for before,after in row['pairs']:
        a=source.count(before);b=source.count(after)
        if a==1 and b==0:
            new=new.replace(before,after,1);oldhits+=1
        elif a==0 and b==1:newhits+=1
        else:die('Version de Hostinger desconocida: '+row['path'])
    if oldhits and newhits:die('Publicacion parcial incompatible: '+row['path'])
    result=(new.replace('\n','\r\n') if crlf else new).encode('utf8')
    if oldhits:syntax(row['path'],result)
    plan.append(dict(path=row['path'],file=p,old=original,new=result,permissions=stat.S_IMODE(p.stat().st_mode),
        created=False,state='pendiente' if oldhits else 'actualizado'))
row=SPECS['newService'];p=get(row['path'],False);target=row['content'].encode('utf8')
if p.exists():
    actual=p.read_bytes()
    if actual!=target:die('Servicio de audio ya existe con contenido diferente.')
    status='actualizado'
else:
    actual=None;status='pendiente';syntax(row['path'],target)
plan.append(dict(path=row['path'],file=p,old=actual,new=target,permissions=0o644,created=True,state=status))
for x in plan:print(x['path']+': '+x['state'])
count=sum(x['state']=='pendiente' for x in plan)
print('Archivos a modificar:',count)
if mode=='--check':
    print('OK: comprobacion sin cambios. No se modificaron archivos.')
    sys.exit(0)
if count==0:
    print('OK: todos los archivos instalados; sin cambios.')
    sys.exit(0)
backup_root.mkdir(parents=True,exist_ok=True,mode=0o700)
os.chmod(str(backup_root),0o700)
backup=Path(tempfile.mkdtemp(prefix='ventas-grabaciones-100-150-',dir=str(backup_root)))
os.chmod(str(backup),0o700)
manifest=[]
for n,x in enumerate(plan):
    original=x['old'];file='%02d.bak'%n
    if original is not None:
        (backup/file).write_bytes(original);os.chmod(str(backup/file),0o600)
    manifest.append(dict(path=x['path'],backup=file,created=x['created'],
        permissions=x['permissions'],old_sha=checksum(original) if original is not None else '',
        new_sha=checksum(x['new'])))
p=backup/'manifest.json'
p.write_text(json.dumps(manifest,indent=2),encoding='utf8');os.chmod(str(p),0o600)
updated=[]
try:
    for x in plan:
        if x['state']!='pendiente':continue
        present=x['file'].read_bytes() if x['file'].exists() else None
        if present!=x['old']:die('Edicion concurrente: '+x['path'])
        replace(x['file'],x['new'],x['permissions']);updated.append(x)
except BaseException:
    for x in reversed(updated):
        present=x['file'].read_bytes() if x['file'].exists() else None
        if present is None or checksum(present)!=checksum(x['new']):continue
        if x['old'] is None:x['file'].unlink()
        else:replace(x['file'],x['old'],x['permissions'])
    raise
print('OK: grabaciones de dos tramos publicadas. Respaldo:',str(backup))
print('Sin cambios SQL, llamadas PBX, grabaciones existentes ni archivos de Analista.')
